    // 3. verify that expected users have the created role dynamically assigned
    assertEquals(2, actual.getDynMembership().getMembers().size());
    assertEquals(new HashSet<>(Arrays.asList("c9b2dec2-00a7-4855-97c0-d854842b4b24", newUserKey)), CollectionUtils.collect(actual.getDynMembership().getMembers(), EntityUtils.<User>keyTransformer(), new HashSet<String>()));
