    roleDAO.delete(actual);
    roleDAO.flush();
    assertNull(entityManager().find(JPADynRoleMembership.class, dynMembershipKey));
    dynRoleMemberships = findDynRoleMemberships(user);
    assertTrue(dynRoleMemberships.isEmpty());
}

