@Test
public void crud() throws IOException {
    final String key = getUUIDString();
    // 1. create (empty) mail template
    MailTemplateTO mailTemplateTO = new MailTemplateTO();
    mailTemplateTO.setKey(key);
    Response response = mailTemplateService.create(mailTemplateTO);
    assertEquals(201, response.getStatus());
    // 2. attempt to read HTML and TEXT -> fail
    try {
        mailTemplateService.getFormat(key, MailTemplateFormat.HTML);
        fail();
    } catch (SyncopeClientException e) {
        assertEquals(ClientExceptionType.NotFound, e.getType());
    }
    try {
        mailTemplateService.getFormat(key, MailTemplateFormat.TEXT);
        fail();
    } catch (SyncopeClientException e) {
        assertEquals(ClientExceptionType.NotFound, e.getType());
    }
    // 3. set TEXT
    String textTemplate = "Hi there, I am ${username}.";
    mailTemplateService.setFormat(key, MailTemplateFormat.TEXT, IOUtils.toInputStream(textTemplate, SyncopeConstants.DEFAULT_CHARSET));
    response = mailTemplateService.getFormat(key, MailTemplateFormat.TEXT);
    assertEquals(200, response.getStatus());
    assertTrue(response.getMediaType().toString().startsWith(MediaType.TEXT_PLAIN));
    assertTrue(response.getEntity() instanceof InputStream);
    assertEquals(textTemplate, IOUtils.toString((InputStream) response.getEntity(), SyncopeConstants.DEFAULT_CHARSET));
    // 3. set HTML
    String htmlTemplate = "<html><body>Hi there, I am ${username}.</body></html>";
    mailTemplateService.setFormat(key, MailTemplateFormat.HTML, IOUtils.toInputStream(htmlTemplate, SyncopeConstants.DEFAULT_CHARSET));
    response = mailTemplateService.getFormat(key, MailTemplateFormat.HTML);
    assertEquals(200, response.getStatus());
    assertTrue(response.getMediaType().toString().startsWith(MediaType.TEXT_HTML));
    assertTrue(response.getEntity() instanceof InputStream);
    assertEquals(htmlTemplate, IOUtils.toString((InputStream) response.getEntity(), SyncopeConstants.DEFAULT_CHARSET));
    // 4. remove HTML
    mailTemplateService.removeFormat(key, MailTemplateFormat.HTML);
    try {
        mailTemplateService.getFormat(key, MailTemplateFormat.HTML);
        fail();
    } catch (SyncopeClientException e) {
        assertEquals(ClientExceptionType.NotFound, e.getType());
    }
    response = mailTemplateService.getFormat(key, MailTemplateFormat.TEXT);
    assertEquals(200, response.getStatus());
    assertTrue(response.getMediaType().toString().startsWith(MediaType.TEXT_PLAIN));
    assertTrue(response.getEntity() instanceof InputStream);
    assertEquals(textTemplate, IOUtils.toString((InputStream) response.getEntity(), SyncopeConstants.DEFAULT_CHARSET));
    // 5. remove mail template
    mailTemplateService.delete(key);
    try {
        mailTemplateService.read(key);
        fail();
    } catch (SyncopeClientException e) {
        assertEquals(ClientExceptionType.NotFound, e.getType());
    }
    try {
        mailTemplateService.getFormat(key, MailTemplateFormat.HTML);
        fail();
    } catch (SyncopeClientException e) {
        assertEquals(ClientExceptionType.NotFound, e.getType());
    }
    try {
        mailTemplateService.getFormat(key, MailTemplateFormat.TEXT);
        fail();
    } catch (SyncopeClientException e) {
        assertEquals(ClientExceptionType.NotFound, e.getType());
    }
}

@Test
public void migrateFromSyncope12() throws InterruptedException {
    // 1. cleanup
    try {
        realmService.delete(MIGRATION_REALM);
    } catch (Exception e) {
        // ignore
    }
    try {
        for (AbstractTaskTO task : taskService.list(new TaskQuery.Builder(TaskType.PULL).resource(RESOURCE_KEY).build()).getResult()) {
            if (PULL_TASK_NAME.equals(PullTaskTO.class.cast(task).getName())) {
                taskService.delete(task.getKey());
            }
        }
    } catch (Exception e) {
        // ignore
    }
    try {
        resourceService.delete(RESOURCE_KEY);
    } catch (Exception e) {
        // ignore
    }
    try {
        for (ConnInstanceTO connInstance : connectorService.list(null)) {
            if (CONNINSTANCE_DISPLAY_NAME.equals(connInstance.getDisplayName())) {
                connectorService.delete(connInstance.getKey());
            }
        }
    } catch (Exception e) {
        // ignore
    }
    try {
        schemaService.delete(SchemaType.PLAIN, MIGRATION_CIPHER_ALGORITHM);
        schemaService.delete(SchemaType.PLAIN, MIGRATION_MEMBERSHIPS_SCHEMA);
        schemaService.delete(SchemaType.PLAIN, MIGRATION_RESOURCES_SCHEMA);
        anyTypeClassService.delete(MIGRATION_ANYTYPE_CLASS);
    } catch (Exception e) {
        // ignore
    }
    // 2. setup
    setupResource(setupConnector(), setupAnyTypeClass());
    setupRealm();
    String pullTaskKey = setupPullTask();
    // 3. execute pull task
    execProvisioningTask(taskService, pullTaskKey, 50, false);
    Thread.sleep(2000L);
    // 4. verify
    UserTO user = userService.read("rossini12");
    assertNotNull(user);
    assertEquals("/" + MIGRATION_REALM, user.getRealm());
    GroupTO group = groupService.read("12 aRoleForPropagation12");
    assertNotNull(group);
    assertEquals("/" + MIGRATION_REALM, group.getRealm());
    // 4a. user plain attrs
    assertEquals("Gioacchino", user.getPlainAttrMap().get("firstname").getValues().get(0));
    assertEquals("Rossini", user.getPlainAttrMap().get("surname").getValues().get(0));
    // 4b. user resources
    assertTrue(user.getResources().contains(RESOURCE_NAME_TESTDB2));
    // 4c. user memberships
    assertTrue(IterableUtils.matchesAny(user.getMemberships(), new Predicate<MembershipTO>() {

        @Override
        public boolean evaluate(final MembershipTO object) {
            return "1 root12".equals(object.getGroupName());
        }
    }));
    // 4d. user password
    assertNotNull(clientFactory.create("bellini12", ADMIN_PWD).self());
    // 4e. group plain attrs
    assertEquals("r12", group.getPlainAttrMap().get("title").getValues().get(0));
    // 4f. group resources
    assertTrue(group.getResources().contains(RESOURCE_NAME_CSV));
}

