public void pull() throws Exception {
    removeTestUsers();
    // -----------------------------
    // Create a new user ... it should be updated applying pull policy
    // -----------------------------
    UserTO inUserTO = new UserTO();
    inUserTO.setRealm(SyncopeConstants.ROOT_REALM);
    inUserTO.setPassword("password123");
