@Test
public void bulkActions() {
    BulkAction bulkAction = new BulkAction();
    for (int i = 0; i < 10; i++) {
        UserTO userTO = getUniqueSampleTO("bulk_" + i + "@apache.org");
        bulkAction.getTargets().add(String.valueOf(createUser(userTO).getAny().getKey()));
    }
    // check for a fail
