        assertEquals(ClientExceptionType.NotFound, e.getType());
    }
    csv = resourceService.read(RESOURCE_NAME_CSV);
    assertNotNull(csv);
    assertEquals(1, csv.getProvisions().size());
    assertTrue(csv.getProvisions().get(0).getVirSchemas().isEmpty());
}

